def trace_sum(nums):
    s = 0
    for x in nums:
        s += x
    return s
print(trace_sum([1, 2, 3]))

def move_zeros(nums):
    write = 0
    for read in range(len(nums)):
        if nums[read] != 0:
            nums[write] = nums[read]
            write += 1
    while write < len(nums):
        nums[write] = 0
        write += 1
    return nums

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        diff = target - x
        if diff in seen:
            return (seen[diff], i)
        seen[x] = i
    return ()
print(two_sum([2, 7, 11, 15], 9))

def find_pair(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        cur = nums[left] + nums[right]
        if cur == target:
            return (left, right)
        elif cur < target:
            left += 1
        else:
            right -= 1
    return ()
